ALTER TABLE clientes ADD COLUMN IF NOT EXISTS observacion TEXT, ADD COLUMN IF NOT EXISTS proximo_seguimiento TIMESTAMP, ADD COLUMN IF NOT EXISTS ultima_gestion TIMESTAMP, ADD COLUMN IF NOT EXISTS cantidad_seguimientos INTEGER DEFAULT 0, ADD COLUMN IF NOT EXISTS empresa_id INTEGER REFERENCES empresas(id), ADD COLUMN IF NOT EXISTS canal TEXT DEFAULT 'cloud', ADD COLUMN IF NOT EXISTS score INTEGER DEFAULT 0, ADD COLUMN IF NOT EXISTS temperatura TEXT DEFAULT 'frio', ADD COLUMN IF NOT EXISTS bot_activo BOOLEAN DEFAULT true, ADD COLUMN IF NOT EXISTS requiere_closer BOOLEAN DEFAULT false, ADD COLUMN IF NOT EXISTS bot_senales JSONB DEFAULT '[]'::jsonb, ADD COLUMN IF NOT EXISTS bot_producto TEXT, ADD COLUMN IF NOT EXISTS bot_paso TEXT, ADD COLUMN IF NOT EXISTS bot_contexto JSONB DEFAULT '{}'::jsonb;

CREATE TABLE IF NOT EXISTS integraciones_whatsapp_qr (id SERIAL PRIMARY KEY, empresa_id INTEGER NOT NULL REFERENCES empresas(id), nombre TEXT NOT NULL, numero_whatsapp TEXT, session_key TEXT NOT NULL UNIQUE, estado TEXT NOT NULL DEFAULT 'desconectado', created_at TIMESTAMP NOT NULL DEFAULT NOW(), updated_at TIMESTAMP NOT NULL DEFAULT NOW());

ALTER TABLE conversaciones ADD COLUMN IF NOT EXISTS empresa_id INTEGER REFERENCES empresas(id), ADD COLUMN IF NOT EXISTS leido BOOLEAN DEFAULT false, ADD COLUMN IF NOT EXISTS media_id TEXT, ADD COLUMN IF NOT EXISTS mime_type TEXT, ADD COLUMN IF NOT EXISTS filename TEXT, ADD COLUMN IF NOT EXISTS whatsapp_qr_id INTEGER REFERENCES integraciones_whatsapp_qr(id);

CREATE TABLE IF NOT EXISTS clientes_whatsapp_qr (id SERIAL PRIMARY KEY, empresa_id INTEGER NOT NULL REFERENCES empresas(id), cliente_id INTEGER NOT NULL REFERENCES clientes(id) ON DELETE CASCADE, whatsapp_qr_id INTEGER NOT NULL REFERENCES integraciones_whatsapp_qr(id) ON DELETE CASCADE, origen TEXT NOT NULL DEFAULT 'whatsapp', created_at TIMESTAMP NOT NULL DEFAULT NOW(), updated_at TIMESTAMP NOT NULL DEFAULT NOW(), UNIQUE(cliente_id, whatsapp_qr_id));
